type Bound<T> = { kind: 'closed' | 'open'; value: T } | { kind: 'unbounded' };
interface Interval<T> { readonly lo: Bound<T>; readonly hi: Bound<T>; }

declare function cmp<T>(a: T, b: T): number;

function contains<T>(iv: Interval<T>, v: T): boolean {
  const lo = iv.lo.kind === 'unbounded' ? -1 : cmp(iv.lo.value, v);
  const hi = iv.hi.kind === 'unbounded' ? -1 : cmp(v, iv.hi.value);
  const loOk = lo < 0 || (lo === 0 && iv.lo.kind === 'closed');
  const hiOk = hi < 0 || (hi === 0 && iv.hi.kind === 'closed');
  return loOk && hiOk;
}
